// extract declarations by brace/bracket matching
function extractBlock(startMarker, openChar){
  const i = s.indexOf(startMarker);
  if(i<0) throw new Error('marker not found: '+startMarker);
  const o = s.indexOf(openChar, i);
  let depth=0;
  for(let j=o;j<s.length;j++){
    if(s[j]===openChar) depth++;
    else if(s[j]===(openChar==='['?']':'}')){
      depth--;
      if(depth===0){
        // include trailing semicolon if present
        let end=j+1;
        if(s[end]===';') end++;
        return s.slice(i,end);
      }
    }
  }
  throw new Error('unbalanced');
}

