{"content":"import fs from 'fs';
const html = fs.readFileSync('chip8_zai-glm-5.3_01.html', 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
if (!m) { console.log('NO SCRIPT'); process.exit(1); }

// ---- DOM stubs ----
const ctxStub = new Proxy({}, { get: (t, k) => (k === 'fillRect' || k === 'fillStyle' ? undefined : () => {}) });
const el = () => ({
  textContent: '', innerHTML: '', className: '', value: '15',
  style: {}, classList: { add(){}, remove(){} },
  appendChild(){}, addEventListener(){},
  getContext: () => new Proxy({}, { get: () => () => {} }),
  onclick: null, oninput: null, onchange: null,
});
const elements = {};
globalThis.document = {
  getElementById: id => (elements[id] ??= el()),
  createElement: () => el(),
};
globalThis.window = globalThis;
globalThis.performance = { now: () => Date.now() };
globalThis.requestAnimationFrame = () => {};
globalThis.setInterval = () => 0;

// append exports so we can reach eval-scope consts
const script = m[1] + '\n;globalThis.__chip=chip; globalThis.__Chip8=Chip8;';
eval(script);

const chip = globalThis.__chip;
const Chip8 = globalThis.__Chip8;
let pass = 0, fail = 0;
function ck(name, cond, info='') {
  if (cond) { pass++; }
  else { fail++; console.log('FAIL:', name, info); }
}

// ---- Test the Chip8 class directly with tiny assembled snippets ----
function run(c, bytes, steps) {
  for (let i = 0; i < bytes.length; i++) c.mem[0x300 + i] = bytes[i];
  c.PC = 0x300;
  for (let i = 0; i < steps; i++) c.step();
}

// 8xy5 SUB
{
  const c = new Chip8();
  run(c, [0x60, 0x05, 0x61, 0x03, 0x80, 0x15], 3);
  ck('SUB', c.V[0] === 2 && c.V[0xF] === 1, `V0=${c.V[0]} VF=${c.V[0xF]}`);
}
// 8xy7 SUBN + borrow
{
  const c = new Chip8();
  run(c, [0x60, 0x03, 0x61, 0x05, 0x80, 0x17], 3);
  ck('SUBN', c.V[0] === 2 && c.V[0xF] === 1, `V0=${c.V[0]} VF=${c.V[0xF]}`);
  const d = new Chip8();
  run(d, [0x60, 0x05, 0x61, 0x03, 0x80, 0x17], 3);
  ck('SUBN borrow', d.V[0] === 0xFE && d.V[0xF] === 0, `V0=${d.V[0]} VF=${d.V[0xF]}`);
}
// 2nnn CALL / 00EE RET
{
  const c = new Chip8();
  run(c, [0x22, 0x10, 0x12, 0x00], 2); // CALL 0x210 ; mem[0x210]=0x1200 JP 0x200
  ck('CALL', c.stack.length === 1 && c.PC === 0x210, `PC=${c.PC.toString(16)} stack=${c.stack.length}`);
  c.mem[0x210] = 0x00; c.mem[0x211] = 0xEE;
  c.step(); // RET
  ck('RET', c.PC === 0x302 && c.stack.length === 0, `PC=${c.PC.toString(16)} stack=${c.stack.length}`);
}
// Ex9E / ExA1
{
  const c = new Chip8();
  c.keys[5] = 1;
  run(c, [0x65, 0x05, 0xE5, 0x9E], 2); // LD V5,5; SKP V5
  ck('SKP', c.PC === 0x304, `PC=${c.PC.toString(16)}`);
  const d = new Chip8();
  d.keys[5] = 0;
  run(d, [0x65, 0x05, 0xE5, 0xA1], 2); // SKNP not pressed -> skip
  ck('SKNP', d.PC === 0x304, `PC=${d.PC.toString(16)}`);
}
// 8xy6 SHR, 8xyE SHL (original COSMAC semantics: VF=Vx lsb, shift Vx)
{
  const c = new Chip8();
  run(c, [0x60, 0x03, 0x80, 0x06], 2);
  ck('SHR', c.V[0] === 1 && c.V[0xF] === 1, `V0=${c.V[0]} VF=${c.V[0xF]}`);
  const d = new Chip8();
  run(d, [0x60, 0x80, 0x80, 0x0E], 2);
  ck('SHL', d.V[0] === 0 && d.V[0xF] === 1, `V0=${d.V[0]} VF=${d.V[0xF]}`);
}
// BCD
{
  const c = new Chip8();
  run(c, [0x60, 0xFE, 0xA3, 0x00, 0xF0, 0x33], 3);
  ck('BCD', c.mem[0x300] === 2 && c.mem[0x301] === 5 && c.mem[0x302] === 4,
    `${c.mem[0x300]} ${c.mem[0x301]} ${c.mem[0x302]}`);
}
// FX55 / FX65
{
  const c = new Chip8();
  run(c, [0x60, 0xAB, 0x61, 0xCD, 0xA3, 0x00, 0xF1, 0x55], 4); // save V0,V1 to 0x300
  ck('FX55', c.mem[0x300] === 0xAB && c.mem[0x301] === 0xCD);
  run(c, [0x60, 0x00, 0x61, 0x00, 0xA3, 0x00, 0xF1, 0x65], 4);
  ck('FX65', c.V[0] === 0xAB && c.V[1] === 0xCD);
}
// timers
{
  const c = new Chip8();
  c.delay = 5;
  for (let i = 0; i < 10; i++) c.tickTimers();
  ck('delay timer', c.delay === 0);
}
// ---- Demo ROM behavior on the live chip ----
const pix = () => chip.display.reduce((a, b) => a + b, 0);
// run many frames
for (let f = 0; f < 300; f++) { for (let i = 0; i < 15; i++) chip.step(); chip.tickTimers(); }
ck('demo draws sprite', pix() > 0, `pix=${pix()}`);

function frame(key) {
  if (key !== undefined) chip.keys[key] = 1;
  // one full pass of the polling loop: 10 instructions per main loop iteration
  for (let i = 0; i < 10; i++) chip.step();
  if (key !== undefined) chip.keys[key] = 0;
}
{
  const y = chip.V[1], x = chip.V[0];
  frame(0x2); // up
  ck('up', chip.V[1] === ((y - 1) & 0xFF), `V1=${chip.V[1]} was ${y}`);
