// ---- Demo ROM behavior on the live chip ----
const pix = () => chip.display.reduce((a, b) => a + b, 0);
// run many frames
for (let f = 0; f < 300; f++) { for (let i = 0; i < 15; i++) chip.step(); chip.tickTimers(); }
ck('demo draws sprite', pix() > 0, `pix=${pix()}`);

function frame(key) {
  // deterministic: step until PC is the main loop head 0x206
  let guard = 0;
  while (chip.PC !== 0x206 && guard++ < 200) chip.step();
  chip.keys[key] = 1;
  // LD V7,k; SKNP; JP handler; erase; move; JP main; LD V2 (=0x206 head again)
  for (let i = 0; i < 6; i++) chip.step();
  chip.keys[key] = 0;
}
{
  const y = chip.V[1], x = chip.V[0];
  frame(0x2); // up
  ck('up', chip.V[1] === ((y - 1) & 0xFF), `V1=${chip.V[1]} was ${y}`);
  frame(0x8); // down
  ck('down', chip.V[1] === y, `V1=${chip.V[1]} was ${y}`);
  frame(0x4); // left
  ck('left', chip.V[0] === ((x - 1) & 0xFF), `V0=${chip.V[0]} was ${x}`);
  frame(0x6); // right
  ck('right', chip.V[0] === x, `V0=${chip.V[0]} was ${x}`);
  ck('sprite stable', pix() > 0, `pix=${pix()}`);
}
// collision flag
{
  const c = new Chip8();
  c.mem[0x320] = 0xFF;
  run(c, [0x60, 0x0A, 0x61, 0x0A, 0xA3, 0x20, 0xD0, 0x11, 0xD0, 0x11], 5); // draw same row twice -> all erased
  ck('collision VF', c.V[0xF] === 1);
}

